<template>
  <div class="page learning-hub">
    <router-link class="learning-back" to="/oj"><UiIcon name="chevron-left" :size="14" />算法题库</router-link>
    <header class="learning-welcome"><div><span class="learning-eyebrow"><span lang="en">LEARNING JOURNEY / </span>算法学习</span><h1>算法训练</h1><p>把每一次练习，连成成长的路径。探索知识点、安排训练，再用复习留下解题方法。</p><div v-if="data" class="learning-welcome-links"><router-link to="/oj">继续做题<UiIcon name="chevron-right" :size="12" /></router-link><button :disabled="loading||busy" @click="load"><UiIcon name="refresh" :size="12" />刷新进度</button></div></div><XiaoRuan mood="cheer" :size="128" /></header>
