      <nav class="learning-tabs" aria-label="算法训练内容"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" :aria-current="tab===t.id?'page':undefined" @click="navigate(t.id)"><UiIcon :name="t.icon" :size="15" />{{ t.name }}<small v-if="t.id==='review'&&dueReviews.length">{{ dueReviews.length }}</small></button></nav>
      <p v-if="mutationError" class="learning-error" role="alert">{{ mutationError }}</p><p v-if="notice" class="learning-notice" role="status">{{ notice }}</p>
      <p v-if="data.truncated" class="learning-footnote">当前显示前 1000 道公开题目的训练记录。</p>
      <section v-show="tab==='path'" class="learning-path">
