        <div class="learning-tracks"><button :class="{active:state.trackId==='all'}" :disabled="busy" @click="chooseTrack('all')"><UiIcon name="layers" :size="16" /><strong>自由探索</strong><span>由基础到进阶</span></button><button v-for="t in SKILL_TRACKS" :key="t.id" :class="{active:state.trackId===t.id}" :disabled="busy" @click="chooseTrack(t.id)"><UiIcon :name="t.icon" :size="16" /><strong>{{ t.name }}</strong><span>{{ t.meta }}</span></button></div>
        <div v-if="track" class="learning-track-description"><span>{{ track.name }}</span><p>{{ track.description }}</p><small>{{ tRequired }} 个核心知识点 · 图谱中的高亮卡片为当前方向重点</small></div>
        <div class="learning-map-controls"><div class="learning-map-scope" role="group" aria-label="知识图谱展示范围"><button :class="{active:mapScope==='all'}" :aria-pressed="mapScope==='all'" @click="mapScope='all'"><UiIcon name="layers" :size="13" />全部知识点<small>{{ report.length }}</small></button><button v-if="track" :class="{active:mapScope==='direction'}" :aria-pressed="mapScope==='direction'" @click="mapScope='direction'"><UiIcon name="route" :size="13" />只看当前方向</button></div><label class="learning-map-search"><UiIcon name="search" :size="14" /><input v-model="topicSearch" type="search" placeholder="搜索知识点、算法或数据结构" aria-label="搜索知识点、算法或数据结构" /></label><span class="learning-map-count" aria-live="polite">显示 {{ pathReport.length }} / {{ report.length }}<small v-if="mapScope!=='all'||topicSearch.trim()">包含前置知识</small></span></div>
        <div class="learning-next-topics"><span><UiIcon name="star" :size="13" />建议下一步</span><button v-for="n in recommendations" :key="n.id" @click="selectNode(n.id)">{{ n.name }}<UiIcon name="chevron-right" :size="12" /></button><span v-if="!recommendations.length" class="learning-muted">可以自由选择知识点，或复习已通过的题目。</span></div>
        <div class="learning-map-legend" aria-label="知识图谱图例"><span><i class="legend-selected" aria-hidden="true"></i>正在查看</span><span><UiIcon name="star" :size="13" />建议下一步</span><span><i class="legend-progress" aria-hidden="true"></i>已通过进度</span><span class="legend-hint">选择知识点，查看思路与配套题目</span></div>
        <div class="learning-path-layout"><div><OjSkillMap :report="pathReport" :selected="selectedNode?.id" :focus="track?.focus||[]" :recommendations="recommendations.map(n=>n.id)" :relations="relations" @select="selectNode" /><div v-if="!pathReport.length" class="learning-map-empty"><XiaoRuan mood="question" :size="64" /><h3>没有找到对应的知识点</h3><p>试试“数组”“二分”或“动态规划”，也可以恢复完整地图。</p><button class="learning-button" @click="topicSearch='';mapScope='all'">查看全部知识点</button></div><details v-else class="learning-level-help"><summary>练习等级和关联线如何计算？</summary><p>等级参考正式提交记录：初步接触为通过不足 3 题，持续练习为通过不足 8 题或通过率不足 45%；训练充分需要至少 8 题且通过率达到 45%。更高等级需要更多题目及进阶训练。题量不足的知识点不会被自动认定为掌握。</p><p>关联线表示建议先学习的知识点，通过一道前置题后即可获得下一步推荐。所有节点都可以探索。多标签题会计入多个知识点，图谱计数不能相加作为通过总题数。</p></details></div>
          <aside v-if="selectedNode" class="learning-topic-detail"><header><span class="learning-topic-context"><UiIcon name="target" :size="14" />正在查看 · {{ LAYER_NAMES[selectedNode.layer] }}</span><h2>{{ selectedNode.name }}</h2><p>{{ selectedNode.intro }}</p></header><div v-if="selectedNode.steps" class="learning-topic-steps"><h3><UiIcon name="book-open" :size="13" />先这样理解</h3><ol><li v-for="step in selectedNode.steps" :key="step">{{ step }}</li></ol></div><div class="learning-topic-numbers"><span><b>{{ selectedNode.stats.ac }}</b>已通过</span><span><b>{{ selectedNode.questions.length }}</b>配套题目</span><span><b>{{ selectedNode.stats.attempts }}</b>正式提交</span></div><div v-if="selectedNode.dependsOn.length" class="learning-prerequisites"><h3>建议先学习</h3><button v-for="id in selectedNode.dependsOn" :key="id" @click="selectNode(id)"><UiIcon :name="report.find(n=>n.id===id)?.stats.ac?'check':'link'" :size="12" />{{ report.find(n=>n.id===id)?.name }}</button></div><div class="learning-topic-problems"><h3>从一道题开始</h3><div v-for="p in selectedNode.questions" :key="p.id" class="learning-question"><OjProblemProgress :progress="p.progress" /><router-link :to="problemLink(p.id)">{{ p.title }}<small>{{ difficultyLabels[p.difficulty] }}</small></router-link><button :aria-label="(isBookmarked(p)?'取消收藏：':'收藏：')+p.title" :aria-pressed="isBookmarked(p)" :disabled="busy" @click="bookmark(p)"><UiIcon name="bookmark" :size="14" /></button></div><div v-if="!selectedNode.questions.length" class="learning-topic-empty"><XiaoRuan mood="idea" :size="60" /><p>本站暂缺配套题目，可先了解概念与前置知识。</p></div></div><button v-if="selectedNode.questions.some(p=>!solved(p))" class="learning-primary learning-full" @click="selectForPlan">用这些题安排训练<UiIcon name="calendar" :size="13" /></button></aside>
        </div>
      </section>
      <section v-show="tab==='plan'" class="learning-plan">
        <div class="learning-section-heading"><div><h2><UiIcon name="calendar" :size="18" />把目标放进每一天</h2><p>通过后自动完成；未完成任务顺延到下一个训练日。</p></div><button v-if="state.plan" class="learning-button" @click="editingPlan=!editingPlan">{{ editingPlan?'收起设置':'重新安排' }}</button></div>
        <template v-if="state.plan"><div class="learning-plan-summary"><div><span>当前计划</span><h3>{{ state.plan.title }}</h3><p>每天 {{ state.plan.dailyTarget }} 题 · {{ state.plan.startedOn }} 开始 · {{ schedule.filter(t=>t.done).length }} / {{ schedule.length }} 已完成</p></div><div class="learning-plan-progress"><svg viewBox="0 0 44 44" aria-hidden="true"><circle cx="22" cy="22" r="18" /><circle cx="22" cy="22" r="18" :stroke-dasharray="`${planPercent*1.13} 113`" /></svg><b>{{ planPercent }}%</b></div></div><div class="learning-week"><article v-for="day in week" :key="day.date" :class="{today:day.date===data.serverDate}"><header><strong>{{ day.label }}</strong><time>{{ day.date.slice(5) }}</time></header><span v-if="state.plan.restDays.includes(weekday(day.date))" class="learning-rest-day">休息日</span><router-link v-for="task in schedule.filter(t=>t.date===day.date)" :key="task.problem.id" :to="problemLink(task.problem.id)"><UiIcon :name="task.done?'check':'code'" :size="12" /><span>{{ task.problem.title }}<small v-if="task.assignedOn<day.date&&!task.done">顺延任务</small></span></router-link><p v-if="!schedule.some(t=>t.date===day.date)&&!state.plan.restDays.includes(weekday(day.date))">{{ schedule.every(t=>t.done)?'计划已完成':'暂无安排' }}</p></article></div><details class="learning-all-tasks"><summary>查看全部 {{ schedule.length }} 项任务</summary><div v-for="task in schedule" :key="task.problem.id" class="learning-task-row"><UiIcon :name="task.done?'check':'clock'" :size="13" /><router-link :to="problemLink(task.problem.id)">{{ task.problem.title }}</router-link><span>{{ task.done?'已通过':task.date }}</span></div></details></template>
        <div v-if="!state.plan||editingPlan" class="learning-plan-editor"><div class="learning-plan-settings"><label>计划名称<input v-model="planTitle" maxlength="80" placeholder="我的训练计划" /></label><label>每天题量<select v-model.number="dailyTarget"><option v-for="n in 10" :key="n" :value="n">{{ n }} 题 / 天</option></select></label><fieldset><legend>每周休息日</legend><label v-for="(name,index) in weekdays" :key="index"><input v-model="restDays" type="checkbox" :value="index" :disabled="restDays.length===6&&!restDays.includes(index)" />{{ name }}</label></fieldset></div><div class="learning-plan-selection"><div class="learning-selection-heading"><h3>选择训练题目 <small>{{ selectedProblems.length }} 道</small></h3><button @click="pickRecommended">按当前方向选 10 题</button><button @click="selectedProblems=[]">清空</button></div><label class="learning-search"><UiIcon name="search" :size="14" /><input v-model="planSearch" placeholder="筛选题目或知识点" aria-label="计划题目筛选" /></label><div class="learning-plan-candidates"><label v-for="p in candidates" :key="p.id"><input v-model="selectedProblems" type="checkbox" :value="String(p.id)" :disabled="selectedProblems.length>=200&&!selectedProblems.includes(String(p.id))" /><span>{{ p.title }}<small>{{ p.tags.join(' · ') }}</small></span><em>{{ difficultyLabels[p.difficulty] }}</em></label><p v-if="!candidates.length">没有未通过的匹配题目。</p></div><footer><span>以全部题目的正式 AC 为完成依据，题单进度分别记录。</span><button class="learning-primary" :disabled="busy||!selectedProblems.length" @click="savePlan"><UiIcon name="calendar" :size="13" />{{ busy?'保存中…':state.plan?'替换训练计划':'创建训练计划' }}</button></footer></div></div>
      </section>
      <section v-show="tab==='review'" class="learning-review">
        <div class="learning-section-heading"><div><h2><UiIcon name="history" :size="18" />复习与私人笔记</h2><p>正式 AC 后按 1 / 3 / 7 / 14 / 30 / 60 天安排复习。轻松前进两档，困难退一档。</p></div><XiaoRuan :mood="dueReviews.length?'question':'approve'" :size="64" /></div>
        <div class="learning-review-layout"><div class="learning-review-list"><div class="learning-review-filters"><button v-for="f in reviewFilters" :key="f.id" :class="{active:reviewFilter===f.id}" @click="reviewFilter=f.id">{{ f.label }} <small>{{ f.count }}</small></button></div><article v-for="p in reviewItems" :key="p.id" class="learning-review-item"><header><OjProblemProgress :progress="p.progress" /><button :class="{active:String(noteProblem?.id)===String(p.id)}" @click="chooseNote(p)">{{ p.title }}</button><router-link :to="problemLink(p.id)">做题<UiIcon name="chevron-right" :size="12" /></router-link></header><p v-if="p.review">第 {{ p.review.stage }} / 6 档 · {{ p.overdue?'已到期':p.dueNow?'今天复习':'下次 '+p.review.due }}</p><p v-else>{{ state.notes[String(p.id)]?'已记录笔记':p.progress.lastVerdict?'最近结果：'+p.progress.lastVerdict:'已收藏' }}</p><div v-if="p.review" class="learning-review-feedback"><span>重新解题后记录感受</span><button :disabled="busy" @click="review(p,'hard')">困难</button><button :disabled="busy" @click="review(p,'ok')">一般</button><button :disabled="busy" @click="review(p,'easy')">轻松</button></div></article><div v-if="!reviewItems.length" class="learning-empty"><XiaoRuan mood="idea" :size="72" /><h3>{{ reviewFilter==='due'?'今天没有待复习题目':'还没有记录' }}</h3><p>可在右侧选择题目写笔记，也可以继续练习。</p><router-link to="/oj">去题库<UiIcon name="chevron-right" :size="12" /></router-link></div></div><aside class="learning-note-editor"><header><UiIcon name="edit" :size="16" /><h3>解题笔记</h3><small>仅自己可见</small></header><label>选择题目<select :value="noteProblem?.id||''" @change="chooseNote(problems.find(p=>String(p.id)===$event.target.value))"><option value="" disabled>选择一道题</option><option v-for="p in problems" :key="p.id" :value="p.id">{{ p.title }}</option></select></label><textarea v-model="noteDraft" maxlength="6000" :disabled="!noteProblem" :placeholder="'用自己的话记下来：\n1. 关键思路是什么？\n2. 哪个边界让我犯错？\n3. 复杂度为何满足要求？\n4. 下次如何更快识别同类问题？'" aria-label="私人解题笔记" /><footer><span>{{ noteDraft.length }} / 6000</span><button class="learning-primary" :disabled="busy||!noteProblem||!noteDirty" @click="saveNote"><UiIcon name="file-save" :size="13" />{{ busy?'保存中…':'保存笔记' }}</button></footer><p class="learning-footnote">清空后保存会删除这篇笔记。笔记与计划保存在账户中，换设备也可继续。</p></aside></div>
      </section>
      <OjTrainingTools v-if="toolsVisited" v-show="tab==='tools'" />
      <section v-show="tab==='stats'" class="learning-stats"><div class="learning-section-heading"><div><h2><UiIcon name="chart" :size="18" />看见训练的积累</h2><p>仅统计当前账户在全部题目中的正式提交，公开题目与题单分别统计。</p></div><XiaoRuan mood="celebrate" :size="64" /></div><div class="learning-stats-grid"><article><h3>近 60 天的练习节奏</h3><div class="learning-activity-grid"><span v-for="day in days" :key="day.date" :class="'level-'+day.level" :title="day.date+'：'+day.attempts+' 次提交，'+day.accepted+' 次通过'" tabindex="0" :aria-label="day.date+'，'+day.attempts+' 次提交，'+day.accepted+' 次通过'" /></div><p class="learning-footnote">{{ days[0]?.date }} — {{ data.serverDate }} · 颜色按整体活跃度计算</p><div class="learning-stats-facts"><span><b>{{ days.reduce((s,d)=>s+d.attempts,0) }}</b>正式提交</span><span><b>{{ days.filter(d=>d.attempts>0).length }}</b>练习天数</span><span><b>{{ problems.filter(p=>p.progress.state==='WRONG'||p.progress.state==='ISSUE').length }}</b>待攻克题目</span></div></article><article><h3>难度覆盖</h3><div v-for="(label,key) in difficultyLabels" :key="key" class="learning-difficulty-stat"><span>{{ label }}</span><div><i :style="{width:ratio(problems.filter(p=>p.difficulty===key&&solved(p)).length,problems.filter(p=>p.difficulty===key).length)+'%'}" /></div><b>{{ problems.filter(p=>p.difficulty===key&&solved(p)).length }} / {{ problems.filter(p=>p.difficulty===key).length }}</b></div><p class="learning-footnote">通过后保持 AC，后续错误不会抹去通过记录。</p></article></div><article class="learning-topic-stats"><h3>知识点覆盖</h3><div v-for="n in report.filter(n=>n.questions.length).sort((a,b)=>b.stats.attempts-a.stats.attempts)" :key="n.id"><button @click="selectNode(n.id);navigate('path')">{{ n.name }}<UiIcon name="chevron-right" :size="12" /></button><span><i :style="{width:ratio(n.stats.ac,n.questions.length)+'%'}" /></span><b>{{ n.stats.ac }} / {{ n.questions.length }}</b><small>{{ n.tier.label }}</small></div></article></section>
      <footer class="learning-attribution">部分知识图谱与标准库资料改编自 <a href="https://github.com/No-Boundry/acm-trainer" target="_blank" rel="noopener noreferrer">ACM-Trainer</a> · <a href="/licenses/acm-trainer.txt" target="_blank" rel="noopener noreferrer">MIT 许可</a></footer>
    </template>
  </div>
</template>
<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useUserStore} from '@/stores/user'
import request from '@/utils/request'
import UiIcon from '@/components/UiIcon.vue'
import XiaoRuan from '@/components/XiaoRuan.vue'
import OjProblemProgress from '@/components/OjProblemProgress.vue'
import OjSkillMap from '@/components/OjSkillMap.vue'
import {SKILL_TRACKS,LAYER_NAMES,skillReport,recommend,filterSkillReport,solved,addDays,weekday,planSchedule,reviewQueue} from '@/utils/ojLearning'
import {createActivityScale} from '../../../../shared/activityIntensity.mjs'
import './learning.css'
const OjTrainingTools=defineAsyncComponent(()=>import('@/components/OjTrainingTools.vue'))
const route=useRoute(),router=useRouter(),user=useUserStore()
const tabs=[{id:'path',name:'学习路径',icon:'route'},{id:'plan',name:'训练计划',icon:'calendar'},{id:'review',name:'复习与笔记',icon:'history'},{id:'tools',name:'工具速查',icon:'code'},{id:'stats',name:'训练统计',icon:'chart'}]
const validTab=value=>tabs.some(t=>t.id===value)?value:'path'
const tab=computed(()=>validTab(route.query.tab)),toolsVisited=ref(tab.value==='tools')
const data=ref(null),loading=ref(false),busy=ref(false),error=ref(''),mutationError=ref(''),notice=ref(''),relations=ref(true)
const problems=computed(()=>data.value?.problems||[]),state=computed(()=>data.value?.state||{trackId:'all',notes:{},bookmarks:[],reviews:{},plan:null})
const trackNames=Object.fromEntries(SKILL_TRACKS.map(t=>[t.id,t.name])),mapScope=ref('all'),topicSearch=ref('')
const tRequired=computed(()=>track.value?.required.length||0)
const track=computed(()=>SKILL_TRACKS.find(t=>t.id===state.value.trackId)),report=computed(()=>skillReport(problems.value)),recommendations=computed(()=>recommend(report.value,state.value.trackId))
const pathReport=computed(()=>filterSkillReport(report.value,{trackId:state.value.trackId,scope:mapScope.value,query:topicSearch.value,selectedId:route.query.node}))
const selectedNode=computed(()=>pathReport.value.find(n=>n.id===route.query.node)||recommendations.value.find(n=>pathReport.value.some(p=>p.id===n.id))||pathReport.value[0])
const completed=computed(()=>problems.value.filter(solved).length),reviews=computed(()=>reviewQueue(problems.value,state.value,data.value?.serverDate||'')),dueReviews=computed(()=>reviews.value.filter(p=>p.dueNow))
const difficultyLabels={EASY:'简单',MEDIUM:'中等',HARD:'困难'},weekdays=['周日','周一','周二','周三','周四','周五','周六']
const dayMap=computed(()=>new Map((data.value?.days||[]).map(d=>[String(d.day??d.DAY).slice(0,10),{attempts:Number(d.attempts??d.ATTEMPTS),accepted:Number(d.accepted??d.ACCEPTED)}])))
const todayAttempts=computed(()=>dayMap.value.get(data.value?.serverDate)?.attempts||0)
const days=computed(()=>{const scale=createActivityScale([...dayMap.value.values()].map(d=>d.attempts));return Array.from({length:60},(_,i)=>{const date=addDays(data.value?.serverDate,i-59),stats=dayMap.value.get(date)||{attempts:0,accepted:0};return {date,...stats,level:scale(stats.attempts)}})})
const schedule=computed(()=>planSchedule(state.value.plan,problems.value,data.value?.serverDate))
const ratio=(value,total)=>total?Math.round(100*value/total):0,planPercent=computed(()=>ratio(schedule.value.filter(t=>t.done).length,schedule.value.length))
const week=computed(()=>Array.from({length:7},(_,i)=>{const date=addDays(data.value?.serverDate,i);return {date,label:i===0?'今天':weekdays[weekday(date)]}}))
const editingPlan=ref(false),planTitle=ref('我的训练计划'),dailyTarget=ref(2),restDays=ref([0]),selectedProblems=ref([]),planSearch=ref('')
const candidates=computed(()=>problems.value.filter(p=>!solved(p)&&[p.title,...p.tags].join(' ').toLowerCase().includes(planSearch.value.trim().toLowerCase())))
const reviewFilter=ref('due'),noteProblem=ref(null),noteDraft=ref(''),noteDrafts=new Map()
const wrongProblems=computed(()=>problems.value.filter(p=>['WRONG','ISSUE'].includes(p.progress.state)))
const reviewFilters=computed(()=>[{id:'due',label:'到期复习',count:dueReviews.value.length},{id:'wrong',label:'错题',count:wrongProblems.value.length},{id:'notes',label:'笔记',count:Object.keys(state.value.notes).length},{id:'bookmarks',label:'收藏',count:state.value.bookmarks.length},{id:'all',label:'全部已通过',count:reviews.value.length}])
const reviewItems=computed(()=>reviewFilter.value==='due'?dueReviews.value:reviewFilter.value==='all'?reviews.value:reviewFilter.value==='wrong'?wrongProblems.value:problems.value.filter(p=>reviewFilter.value==='notes'?Object.hasOwn(state.value.notes,String(p.id)):isBookmarked(p)))
const noteDirty=computed(()=>noteDraft.value!==(state.value.notes[String(noteProblem.value?.id)]||''))
let controller,generation=0,disposed=false,noticeTimer
function navigate(value){router.push({query:{...route.query,tab:value}})}
function selectNode(id){if(!pathReport.value.some(n=>n.id===id))topicSearch.value='';router.replace({query:{...route.query,node:id}})}
function problemLink(id){return {path:'/oj/'+id,query:{from:router.resolve({path:'/oj/learning',query:{tab:tab.value,node:selectedNode.value?.id}}).href}}}
function isBookmarked(p){return state.value.bookmarks.some(id=>String(id)===String(p.id))}
function chooseNote(p){if(!p)return;if(noteProblem.value&&noteDirty.value)noteDrafts.set(String(noteProblem.value.id),noteDraft.value);noteProblem.value=p;noteDraft.value=noteDrafts.get(String(p.id))??state.value.notes[String(p.id)]??''}
async function load(){
  const current=++generation;controller?.abort();controller=new AbortController();loading.value=true;error.value=''
  try{const {data:result}=await request.get('/api/oj/learning',{signal:controller.signal});if(disposed||current!==generation)return;data.value=result;selectedProblems.value=selectedProblems.value.filter(id=>result.problems.some(p=>String(p.id)===id));const requested=result.problems.find(p=>String(p.id)===String(route.query.problem));if(requested&&!noteProblem.value)chooseNote(requested);else if(noteProblem.value&&!result.problems.some(p=>String(p.id)===String(noteProblem.value.id))){noteProblem.value=null;noteDraft.value=''}}
  catch(e){if(!disposed&&current===generation&&e.code!=='ERR_CANCELED')error.value=e.message||'加载失败'}finally{if(current===generation)loading.value=false}
}
async function mutate(payload,message){
  if(busy.value||!data.value)return false;busy.value=true;mutationError.value='';notice.value=''
  try{const result=await request.post('/api/oj/learning/state',{...payload,version:data.value.version});if(disposed)return false;data.value.version=result.data.version;await load();notice.value=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',3000);return true}
  catch(e){if(!disposed)mutationError.value=e.message||'保存失败';return false}finally{busy.value=false}
}
async function chooseTrack(trackId){if(trackId!==state.value.trackId&&await mutate({action:'TRACK',trackId},'学习方向已保存')){mapScope.value='all';topicSearch.value='';const query={...route.query};delete query.node;router.replace({query})}}
function bookmark(p){mutate({action:'BOOKMARK',problemId:p.id,bookmarked:!isBookmarked(p)},isBookmarked(p)?'已取消收藏':'已加入收藏')}
function review(p,ease){mutate({action:'REVIEW',problemId:p.id,ease},'复习反馈已保存，下次复习已安排')}
async function saveNote(){const id=String(noteProblem.value.id),text=noteDraft.value;if(await mutate({action:'NOTE',problemId:id,text},'笔记已保存')){if(noteDrafts.get(id)===text||(String(noteProblem.value?.id)===id&&noteDraft.value===text))noteDrafts.delete(id);if(String(noteProblem.value?.id)===id&&noteDraft.value===text)noteDraft.value=text.trim()}}
function selectForPlan(){selectedProblems.value=selectedNode.value.questions.filter(p=>!solved(p)).slice(0,200).map(p=>String(p.id));planTitle.value=selectedNode.value.name+'训练';editingPlan.value=true;navigate('plan')}
function pickRecommended(){const pool=[...recommendations.value.flatMap(n=>n.questions),...problems.value];selectedProblems.value=[...new Set(pool.filter(p=>!solved(p)).map(p=>String(p.id)))].slice(0,10);planTitle.value=track.value?trackNames[track.value.id]+'训练':'我的训练计划'}
async function savePlan(){if(await mutate({action:'PLAN',title:planTitle.value,dailyTarget:dailyTarget.value,restDays:restDays.value,problemIds:selectedProblems.value},'训练计划已保存'))editingPlan.value=false}
watch(tab,value=>{if(value==='tools')toolsVisited.value=true})
watch(()=>route.query.problem,id=>{const p=problems.value.find(p=>String(p.id)===String(id));if(p)chooseNote(p)})
watch(()=>user.user?.id,(id,previous)=>{if(previous==null||id===previous)return;controller?.abort();++generation;data.value=null;noteProblem.value=null;noteDraft.value='';noteDrafts.clear();selectedProblems.value=[];load()})
onMounted(load)
onBeforeUnmount(()=>{disposed=true;++generation;controller?.abort();clearTimeout(noticeTimer)})
</script>
